import { IDomainState } from '../../../../core/state/gameState';
import { PlayerId } from '../../../../core/coordinates';
import { ITopology } from '../../../../core/topology/types';
import { OfficialSpellRules } from '../../../../engine/variants/spells/OfficialSpellRules';
import { SpellChessMoveGenerator } from './SpellChessMoveGenerator';
import { SpellChessTurnAction, SpellResources } from './SpellChessTurnAction';
import { SPELL_CHESS_MATE_SCORE } from './SpellChessPositionEvaluator';

export interface MaterialInspection {
  score: number;
  reply?: SpellChessTurnAction;
  line: SpellChessTurnAction[];
  repliesExamined: number;
  simulations: number;
  outcome?: 'WIN' | 'LOSS' | 'DRAW';
}

/** Legal, spell-aware exchange search. Geometry alone never proves a capture or recapture. */
export class SpellChessMaterialSafety {
  public static readonly values: Readonly<Record<string, number>> = { PAWN: 100, KNIGHT: 320, BISHOP: 330, ROOK: 500, QUEEN: 900, KING: 0 };

  public static balance(domain: IDomainState, player: PlayerId): number {
    return OfficialSpellRules.pieces(domain).reduce((sum, p) => sum +
      (p.ownerId === player ? 1 : -1) * (this.values[p.variantId] ?? 0), 0);
  }

  public static resources(domain: IDomainState): SpellResources {
    const s = OfficialSpellRules.getState(domain);
    const c = domain.activePlayer === 'P1' ? s.whiteCharges : s.blackCharges;
    return { freezeRemaining: c.freezeCharges, jumpRemaining: c.jumpCharges,
      freezeCooldown: c.freezeCooldownTurns, jumpCooldown: c.jumpCooldownTurns };
  }

  /** At most three capture plies, including recaptures and terminal counterattacks anywhere. */
  public static inspect(domain: IDomainState, player: PlayerId, topology: ITopology,
    checkTime: () => void = () => {}, targetSquare?: string, remaining = 3, ply = 1): MaterialInspection {
    const terminal = domain.isGameOver ? domain.winnerId === null ? 0 :
      domain.winnerId === player ? SPELL_CHESS_MATE_SCORE - ply : -SPELL_CHESS_MATE_SCORE + ply : undefined;
    if (terminal !== undefined) return { score: terminal, line: [], repliesExamined: 0, simulations: 0,
      outcome: domain.winnerId === null ? 'DRAW' : domain.winnerId === player ? 'WIN' : 'LOSS' };
    const win = SpellChessMoveGenerator.findKingCapture(domain, domain.activePlayer, topology);
    if (win) return { score: domain.activePlayer === player ? SPELL_CHESS_MATE_SCORE - ply - 1 : -SPELL_CHESS_MATE_SCORE + ply + 1,
      reply: win, line: [win], repliesExamined: 1, simulations: 0, outcome: domain.activePlayer === player ? 'WIN' : 'LOSS' };
    let best: MaterialInspection = { score: this.balance(domain, player), line: [], repliesExamined: 0, simulations: 0 };
    if (!remaining) return best;
    const maximize = domain.activePlayer === player;
    // Standing pat means declining a local exchange, not declaring the actual position quiet.
    for (const action of SpellChessMoveGenerator.iterateTurnActions(domain, domain.activePlayer, topology,
      this.resources(domain), [], [], undefined, true, targetSquare)) {
      checkTime();
      const next = OfficialSpellRules.simulate(domain, action, topology);
      const immediateScore = this.balance(next, player);
      // A capture which cannot worsen the current bound needs no recapture expansion.
      // Terminal replies still take precedence over material.
      const kingReply = SpellChessMoveGenerator.findKingCapture(next, next.activePlayer, topology);
      let value: MaterialInspection;
      if (!next.isGameOver && !kingReply && (maximize ? immediateScore <= best.score : immediateScore >= best.score)) {
        value = { score: immediateScore, line: [], repliesExamined: 0, simulations: 0 };
      } else value = this.inspect(next, player, topology, checkTime, action.move.to, remaining - 1, ply + 1);
      best.repliesExamined++; best.simulations += 1 + value.simulations;
      if (maximize ? value.score > best.score : value.score < best.score) {
        best = { ...best, score: value.score, reply: action, line: [action, ...value.line], outcome: value.outcome };
      }
    }
    return best;
  }
}

import { IDomainState } from '../../../../core/state/gameState';
import { PlayerId, asCoordinateKey, asEntityId } from '../../../../core/coordinates';
import { ITopology } from '../../../../core/topology/types';
import { RulesEngine } from '../../../../engine/rules/RulesEngine';
import { OfficialSpellRules } from '../../../../engine/variants/spells/OfficialSpellRules';
import { SpellAction, SpellChessTurnAction, SpellResources } from './SpellChessTurnAction';
import { SpellChessThreatAnalyzer } from './SpellChessThreatAnalyzer';
import { OfficialSpellEngine } from '../../../../engine/variants/spells/OfficialSpellEngine';

export class SpellChessMoveGenerator {
  public static generateTurnActions(
    domain: IDomainState, actingPlayer: PlayerId, topology: ITopology, resources: SpellResources,
    _activeFrozenCoords: readonly string[] = [], _activeJumpCoords: readonly string[] = [],
    _fallbackLegalMoves?: readonly { from: string; to: string; pieceId: string; isCapture?: boolean; promotion?: string }[]
  ): SpellChessTurnAction[] {
    return [...this.iterateTurnActions(domain, actingPlayer, topology, resources,
      _activeFrozenCoords, _activeJumpCoords, _fallbackLegalMoves)];
  }

  /** Normal turns are available before expanding magical combinations. No legal spell layer is dropped. */
  public static *iterateTurnActions(
    domain: IDomainState, actingPlayer: PlayerId, topology: ITopology, resources: SpellResources,
    _activeFrozenCoords: readonly string[] = [], _activeJumpCoords: readonly string[] = [],
    _fallbackLegalMoves?: readonly { from: string; to: string; pieceId: string; isCapture?: boolean; promotion?: string }[],
    capturesOnly = false, targetSquare?: string,
  ): Generator<SpellChessTurnAction, void, undefined> {
    // Legacy geometric arrays and supplied move lists are not authoritative.
    void _activeFrozenCoords; void _activeJumpCoords; void _fallbackLegalMoves;
    const base = { ...domain, activePlayer: actingPlayer };
    const enemy: PlayerId = actingPlayer === 'P1' ? 'P2' : 'P1';
    const probe = OfficialSpellRules.sync({ ...base, activePlayer: enemy,
      metadata: { ...base.metadata, hasCastSpellThisTurn: false } },
      OfficialSpellEngine.advanceTurn(OfficialSpellRules.getState(base), actingPlayer === 'P1' ? 'WHITE' : 'BLACK'));
    const threats = capturesOnly ? [] : OfficialSpellRules.pieces(base).filter(p => p.ownerId === actingPlayer &&
      ['QUEEN', 'ROOK', 'BISHOP', 'KNIGHT'].includes(p.variantId)).flatMap(piece => {
      const attackers = new Set([...this.findCaptures(probe, enemy, topology, piece.position)].map(reply => reply.move.from));
      return [...attackers].map(attacker => ({ piece, attacker }));
    });
    const spells: SpellAction[] = [{ type: 'NONE' }];
    if (!base.metadata?.hasCastSpellThisTurn) {
      if (resources.jumpRemaining > 0 && resources.jumpCooldown === 0) {
        for (const piece of OfficialSpellRules.pieces(base)) {
          if (!piece.metadata?.canBeJumpedOver) spells.push({ type: 'JUMP', targetSquare: piece.position });
        }
      }
      if (resources.freezeRemaining > 0 && resources.freezeCooldown === 0) {
        // Enumerate every distinct affected piece set, including offset defensive Freezes.
        const seen = new Set<string>();
        const pieces = OfficialSpellRules.pieces(base);
        for (let x = 0; x < 8; x++) for (let y = 0; y < 8; y++) {
          const affected = pieces.filter((p) => {
            const [px, py] = SpellChessThreatAnalyzer.parseCoord(p.position);
            return Math.abs(x - px) <= 1 && Math.abs(y - py) <= 1;
          }).map((p) => p.id).sort().join('|');
          if (!affected || seen.has(affected)) continue;
          seen.add(affected);
          const targetSquare = `${x},${y}`;
          if ((OfficialSpellRules.getState(base).activeFrozenCoordinates[targetSquare] ?? 0) === 2) continue;
          spells.push({ type: 'FREEZE', targetSquare });
        }
      }
    }
    const defenseSpellScore = (spell: SpellAction) => spell.type !== 'FREEZE' ? 0 : threats.reduce((score,t) => {
      const [x,y] = SpellChessThreatAnalyzer.parseCoord(spell.targetSquare);
      const [ax,ay] = SpellChessThreatAnalyzer.parseCoord(t.attacker);
      return score + (Math.abs(x-ax) <= 1 && Math.abs(y-ay) <= 1 ?
        t.piece.variantId === 'QUEEN' ? 900 : t.piece.variantId === 'ROOK' ? 500 : 320 : 0);
    }, 0);
    const defensiveSpell = (spell: SpellAction) => defenseSpellScore(spell) > 0;
    spells.sort((a,b) => (a.type === 'NONE' ? -100000 : -defenseSpellScore(a)) -
      (b.type === 'NONE' ? -100000 : -defenseSpellScore(b)));
    const deferredNormal: SpellChessTurnAction[] = [];
    const deferredJump: SpellChessTurnAction[] = [];
    let normalFlushed = false;
    for (const spell of spells) {
      if (spell.type === 'FREEZE' && !defensiveSpell(spell) && !normalFlushed) {
        yield* deferredNormal; normalFlushed = true;
      }
      const next = this.cloneAndApplySpell(base, spell, actingPlayer);
      const actions: SpellChessTurnAction[] = [];
      for (const move of RulesEngine.getLegalMoves(next, topology)) {
        if (capturesOnly && !move.isCapture && !move.isPromotion) continue;
        if (targetSquare && move.to !== targetSquare) continue;
        if (spell.type === 'JUMP' && !SpellChessThreatAnalyzer.rayPassesThroughSquare(move.from, move.to, spell.targetSquare)) continue;
        const promotions = move.isPromotion ? (move.promotionOptions ?? ['QUEEN', 'ROOK', 'BISHOP', 'KNIGHT']) : [undefined];
        for (const promotion of promotions) actions.push({ spell, move: {
          pieceId: move.pieceId, from: move.from, to: move.to,
          isCapture: move.isCapture, promotion,
        } });
      }
      const king = SpellChessThreatAnalyzer.findKingCoord(base, actingPlayer === 'P1' ? 'P2' : 'P1');
      const defensePriority = (a: SpellChessTurnAction) => threats.reduce((score,t) => score +
        (a.move.pieceId === t.piece.id ? (t.piece.variantId === 'QUEEN' ? 90000 : t.piece.variantId === 'ROOK' ? 50000 : 32000) :
          a.move.to === t.attacker ? 60000 : SpellChessThreatAnalyzer.rayPassesThroughSquare(t.attacker,t.piece.position,a.move.to) ? 10000 : 0), 0);
      actions.sort((a, b) => defensePriority(b) - defensePriority(a) + this.priority(b, base, king) - this.priority(a, base, king));
      let normalCount = 0;
      for (const action of actions) {
        if (spell.type === 'NONE' && ((threats.length && !defensePriority(action)) ||
          (!capturesOnly && normalCount >= 2 && !action.move.isCapture))) deferredNormal.push(action);
        else if (spell.type === 'JUMP' && !capturesOnly && !action.move.isCapture && !defensePriority(action)) deferredJump.push(action);
        else { yield action; if (spell.type === 'NONE') normalCount++; }
      }
    }
    if (!normalFlushed) yield* deferredNormal;
    yield* deferredJump;
  }

  public static cloneAndApplySpell(domain: IDomainState, spell: SpellAction, actingPlayer?: PlayerId): IDomainState {
    return OfficialSpellRules.cast({ ...domain, activePlayer: actingPlayer ?? domain.activePlayer }, spell, actingPlayer ?? domain.activePlayer);
  }

  /** Exhaustive immediate royal captures: direct moves and every Jump that can open a ray. */
  public static findKingCapture(domain: IDomainState, player: PlayerId, topology: ITopology): SpellChessTurnAction | undefined {
    if (domain.isGameOver) return undefined;
    const king = SpellChessThreatAnalyzer.findKingCoord(domain, player === 'P1' ? 'P2' : 'P1');
    if (!king) return undefined;
    return this.findCapture(domain, player, topology, king);
  }

  public static findCapture(domain: IDomainState, player: PlayerId, topology: ITopology, target: string): SpellChessTurnAction | undefined {
    for (const action of this.findCaptures(domain, player, topology, target)) return action;
    return undefined;
  }

  /** All direct/Jump attackers, for ordering multi-attacker defenses. Final safety also searches Freeze replies. */
  public static *findCaptures(domain: IDomainState, player: PlayerId, topology: ITopology,
    target: string): Generator<SpellChessTurnAction, void, undefined> {
    if (domain.isGameOver) return;
    const base = { ...domain, activePlayer: player };
    function* find(state: IDomainState, spell: SpellAction): Generator<SpellChessTurnAction, void, undefined> {
      for (const piece of OfficialSpellRules.pieces(state)) {
        if (piece.ownerId !== player || piece.metadata?.isFrozen) continue;
        const move = RulesEngine.getLegalMovesForPiece(piece, state, topology).find((m) => m.to === target);
        if (move) yield { spell, move: { pieceId: move.pieceId, from: move.from, to: move.to, isCapture: true } };
      }
    }
    yield* find(base, { type: 'NONE' });
    const state = OfficialSpellRules.getState(base);
    const charges = player === 'P1' ? state.whiteCharges : state.blackCharges;
    if (base.metadata?.hasCastSpellThisTurn || charges.jumpCharges <= 0 || charges.jumpCooldownTurns > 0) return;
    const rays = SpellChessThreatAnalyzer.detectOneObstacleJumpRays(base, target, player === 'P1' ? 'P2' : 'P1');
    for (const targetSquare of new Set(rays.map(ray => ray.obstacleCoord))) {
      const spell: SpellAction = { type: 'JUMP', targetSquare };
      yield* find(OfficialSpellRules.cast(base, spell, player), spell);
    }
  }

  private static priority(action: SpellChessTurnAction, domain: IDomainState, king: string | null): number {
    if (action.move.to === king) return 1_000_000 - (action.spell.type === 'NONE' ? 0 : 1);
    const victim = domain.boardEntities[domain.occupancy[asCoordinateKey(action.move.to)]];
    const values: Record<string, number> = { QUEEN: 900, ROOK: 500, BISHOP: 330, KNIGHT: 320, PAWN: 100 };
    const mover = domain.boardEntities[asEntityId(action.move.pieceId)];
    const attackerValue = mover?.type === 'PIECE' ? values[mover.variantId] ?? 0 : 0;
    const [fx,fy] = SpellChessThreatAnalyzer.parseCoord(action.move.from);
    const [tx,ty] = SpellChessThreatAnalyzer.parseCoord(action.move.to);
    const activity = (Math.abs(fx-3.5)+Math.abs(fy-3.5)-Math.abs(tx-3.5)-Math.abs(ty-3.5))*3 +
      (mover?.type === 'PIECE' && !mover.hasMoved && ['KNIGHT','BISHOP'].includes(mover.variantId) ? 40 : 0);
    return (victim?.type === 'PIECE' ? (values[victim.variantId] ?? 0) * 10 - attackerValue : 0) +
      (action.move.promotion ? 8000 : 0) + activity - (action.spell.type === 'NONE' ? 0 : 50);
  }
}

/**
 * ChessInReact - Spell Chess Position Evaluator (Spec 15 § 4 Estratégia 7, RF-15-06)
 *
 * Evaluates game positions specifically for Spell Chess:
 * - Terminal priority: King capture produces instant mate score (+/- 100,000).
 * - Jump threat dynamics: 1-obstacle rays to King are heavily penalized/rewarded based on Jump availability.
 * - Freeze awareness: Evaluates frozen kings and major pieces, taking account of expiration.
 * - Resource economics: Models value of remaining Freeze and Jump charges and cooldowns.
 */

import { IDomainState } from '../../../../core/state/gameState';
import { PlayerId } from '../../../../core/coordinates/types';
import { IPieceEntity } from '../../../../core/entities/types';
import { SpellChessThreatAnalyzer } from './SpellChessThreatAnalyzer';
import { SpellResources } from './SpellChessTurnAction';
import { OfficialSpellRules } from '../../../../engine/variants/spells/OfficialSpellRules';
import { CheckValidator } from '../../../../engine/rules/CheckValidator';
import { ITopology } from '../../../../core/topology/types';

export const SPELL_CHESS_MATE_SCORE = 100_000;

const PIECE_VALUES: Record<string, number> = {
  PAWN: 100,
  P: 100,
  KNIGHT: 320,
  N: 320,
  BISHOP: 330,
  B: 330,
  ROOK: 500,
  R: 500,
  QUEEN: 900,
  Q: 900,
  KING: 0,
  K: 0,
};

export class SpellChessPositionEvaluator {
  public static evaluate(
    domain: IDomainState,
    actingPlayer: PlayerId,
    topology: ITopology,
    playerResources: SpellResources,
    opponentResources: SpellResources,
    _activeFrozenCoords: readonly string[] = [],
    _activeJumpCoords: readonly string[] = [],
    ply: number = 0
  ): number {
    void _activeFrozenCoords; void _activeJumpCoords;
    const opponentPlayer: PlayerId = actingPlayer === 'P1' ? 'P2' : 'P1';

    // 1. Terminal Royal Capture Verification
    let friendlyKingCaptured = false;
    let opponentKingCaptured = false;
    for (const entity of Object.values(domain.boardEntities)) {
      if (
        entity &&
        entity.type === 'PIECE' &&
        (entity.variantId.toUpperCase() === 'KING' || entity.variantId.toUpperCase() === 'K')
      ) {
        if (entity.ownerId === actingPlayer && entity.isCaptured) {
          friendlyKingCaptured = true;
        } else if (entity.ownerId === opponentPlayer && entity.isCaptured) {
          opponentKingCaptured = true;
        }
      }
    }

    if (opponentKingCaptured) {
      return SPELL_CHESS_MATE_SCORE - ply;
    }
    if (friendlyKingCaptured) {
      return -SPELL_CHESS_MATE_SCORE + ply;
    }

    const friendlyKingCoord = SpellChessThreatAnalyzer.findKingCoord(domain, actingPlayer);
    const opponentKingCoord = SpellChessThreatAnalyzer.findKingCoord(domain, opponentPlayer);

    // 2. Material & Positional Evaluation
    let materialScore = 0;
    let pieceActivityScore = 0;

    for (const entity of Object.values(domain.boardEntities)) {
      if (!entity || entity.type !== 'PIECE' || entity.isCaptured) continue;
      const piece = entity as IPieceEntity;
      const variant = piece.variantId.toUpperCase();
      const isKing = variant === 'KING' || variant === 'K';
      const baseValue = isKing ? 0 : (PIECE_VALUES[variant] ?? 100);
      const isFriendly = piece.ownerId === actingPlayer;

      const [px, py] = SpellChessThreatAnalyzer.parseCoord(piece.position);
      let activity = 0;
      if (!isKing) {
        // Central proximity bonus for active non-king combatants
        const centerDist = Math.abs(px - 3.5) + Math.abs(py - 3.5);
        activity = (7 - centerDist) * 3;
      } else {
        // King safety: penalize venturing away from back rank into exposed center
        const homeRank = isFriendly
          ? (actingPlayer === 'P1' ? 0 : 7)
          : (actingPlayer === 'P1' ? 7 : 0);
        const rankDist = Math.abs(py - homeRank);
        activity = -rankDist * 25;
      }

      if (isFriendly) {
        materialScore += baseValue;
        pieceActivityScore += activity;
      } else {
        materialScore -= baseValue;
        pieceActivityScore -= activity;
      }
    }

    // Tactical wins are proved by legal composite actions in search, not frozen-king heuristics.
    const friendlyRays = opponentKingCoord ? SpellChessThreatAnalyzer.detectOneObstacleJumpRays(domain, opponentKingCoord, opponentPlayer).length : 0;
    const enemyRays = friendlyKingCoord ? SpellChessThreatAnalyzer.detectOneObstacleJumpRays(domain, friendlyKingCoord, actingPlayer).length : 0;
    const jumpScore = (playerResources.jumpRemaining > 0 && playerResources.jumpCooldown === 0 ? friendlyRays * 60 : 0) -
      (opponentResources.jumpRemaining > 0 && opponentResources.jumpCooldown === 0 ? enemyRays * 60 : 0);
    let frozenScore = 0;
    for (const piece of OfficialSpellRules.pieces(domain)) {
      if (!piece.metadata?.isFrozen) continue;
      const value = Math.min(8, (PIECE_VALUES[piece.variantId.toUpperCase()] ?? 0) / 100);
      frozenScore += piece.ownerId === actingPlayer ? -value : value;
    }
    const checkScore = (CheckValidator.isRoyalInCheck(opponentPlayer, domain, topology) ? 35 : 0) -
      (CheckValidator.isRoyalInCheck(actingPlayer, domain, topology) ? 35 : 0);
    const economy = (playerResources.freezeRemaining - opponentResources.freezeRemaining) * 60 +
      (playerResources.jumpRemaining - opponentResources.jumpRemaining) * 100;
    return Math.max(-20000, Math.min(20000, materialScore + pieceActivityScore + jumpScore + frozenScore + checkScore + economy));
  }
}

import { IDomainState } from '../../../../core/state/gameState';
import { PlayerId, asCoordinateKey } from '../../../../core/coordinates';
import { ITopology } from '../../../../core/topology/types';
import { OfficialSpellEngine, IPlayerSpellCharges } from '../../../../engine/variants/spells/OfficialSpellEngine';
import { OfficialSpellRules } from '../../../../engine/variants/spells/OfficialSpellRules';
import { SpellChessTurnAction, SpellResources, SpellChessDecisionTrace, CandidateDiagnostic } from './SpellChessTurnAction';
import { SpellChessMoveGenerator } from './SpellChessMoveGenerator';
import { SpellChessPositionEvaluator, SPELL_CHESS_MATE_SCORE as MATE } from './SpellChessPositionEvaluator';
import { SpellChessTranspositionTable } from './SpellChessTranspositionTable';
import { SpellChessMaterialSafety } from './SpellChessMaterialSafety';

export interface ISpellChessSearchResult {
  readonly bestAction: SpellChessTurnAction;
  readonly evaluationCentipawns: number;
  readonly depthReached: number;
  readonly nodesEvaluated: number;
  readonly elapsedMs: number;
  readonly trace: SpellChessDecisionTrace;
}
const opposite = (p: PlayerId): PlayerId => p === 'P1' ? 'P2' : 'P1';
interface NodeResult { score: number; pv: SpellChessTurnAction[] }
class SearchTimeout extends Error {}

export class SpellChessSearch {
  private readonly tt: SpellChessTranspositionTable;
  private nodes = 0;
  private qnodes = 0;
  private deadline = 0;
  private timedOut = false;
  constructor(ttSize = 32768) { this.tt = new SpellChessTranspositionTable(ttSize); }

  public static resources(domain: IDomainState, player: PlayerId): SpellResources {
    const spells = OfficialSpellRules.getState(domain);
    const c = player === 'P1' ? spells.whiteCharges : spells.blackCharges;
    return { freezeRemaining: c.freezeCharges, jumpRemaining: c.jumpCharges,
      freezeCooldown: c.freezeCooldownTurns, jumpCooldown: c.jumpCooldownTurns };
  }

  public searchBestTurnAction(domain: IDomainState, player: PlayerId, topology: ITopology,
    resources: SpellResources, opponentResources: SpellResources, timeBudgetMs = 2500, maxDepth = 5,
    _activeFrozenCoords: readonly string[] = [], _activeJumpCoords: readonly string[] = [],
    _fallbackLegalMoves?: readonly { from: string; to: string; pieceId: string; isCapture?: boolean; promotion?: string }[]
  ): ISpellChessSearchResult {
    void _activeFrozenCoords; void _activeJumpCoords; void _fallbackLegalMoves;
    const start = performance.now();
    this.deadline = start + Math.max(1, timeBudgetMs);
    this.nodes = 0; this.qnodes = 0; this.timedOut = false; this.tt.clear();
    const charges = (r: SpellResources): IPlayerSpellCharges => ({ freezeCharges: r.freezeRemaining,
      jumpCharges: r.jumpRemaining, freezeCooldownTurns: r.freezeCooldown, jumpCooldownTurns: r.jumpCooldown });
    let root: IDomainState = { ...domain, activePlayer: player };
    if (!domain.metadata?.officialSpellState) {
      const initial = OfficialSpellEngine.createInitialState();
      root = { ...root, metadata: { ...root.metadata, officialSpellState: { ...initial,
        whiteCharges: charges(player === 'P1' ? resources : opponentResources),
        blackCharges: charges(player === 'P2' ? resources : opponentResources),
        activeFrozenPieceIds: Object.fromEntries(OfficialSpellRules.pieces(domain)
          .filter((p) => p.metadata?.isFrozen).map((p) => [p.id, 1])),
        activeJumpPieceIds: Object.fromEntries(OfficialSpellRules.pieces(domain)
          .filter((p) => p.metadata?.canBeJumpedOver).map((p) => [p.id, 1])),
      } } };
    }
    const immediate = SpellChessMoveGenerator.findKingCapture(root, player, topology);
    const actions = immediate ? [immediate] : SpellChessMoveGenerator.iterateTurnActions(root, player, topology, SpellChessSearch.resources(root, player));
    const rootMaterial = SpellChessMaterialSafety.balance(root, player);
    const inspectionDeadline = start + Math.max(1, timeBudgetMs * 0.45);
    let rootExhausted = true;
    const diagnostics: CandidateDiagnostic[] = [];
    const children: Array<{ action: SpellChessTurnAction; state: IDomainState; diagnostic: CandidateDiagnostic }> = [];
    for (const action of actions) {
      // Never select an action whose opponent captures have not been inspected.
      // Complete at least one executable inspection even under a tiny budget.
      if (performance.now() >= inspectionDeadline && children.some((c) => !c.diagnostic.allowsImmediateKingCapture &&
        (c.diagnostic.materialLossCp ?? Infinity) <= 200)) {
        rootExhausted = false; break;
      }
      const targetId = root.occupancy[asCoordinateKey(action.move.to)];
      const target = targetId ? root.boardEntities[targetId] : undefined;
      const values: Record<string, number> = { QUEEN: 900, ROOK: 500, BISHOP: 330, KNIGHT: 320, PAWN: 100 };
      const d: CandidateDiagnostic = { action, legal: true, score: 0, completedDepth: 0,
        allowsImmediateKingCapture: false, safetyChecked: false, usedFallback: false,
        capturedMaterialCp: target?.type === 'PIECE' ? values[target.variantId] ?? 0 : 0 };
      diagnostics.push(d);
      try {
        const next = OfficialSpellRules.simulate(root, action, topology);
        this.nodes++;
        const reply = SpellChessMoveGenerator.findKingCapture(next, opposite(player), topology);
        d.safetyChecked = true;
        d.allowsImmediateKingCapture = Boolean(reply);
        d.opponentBestReply = reply;
        const canInterrupt = children.some((c) => !c.diagnostic.allowsImmediateKingCapture && (c.diagnostic.materialLossCp ?? Infinity) <= 200);
        const material = SpellChessMaterialSafety.inspect(next, player, topology,
          canInterrupt ? () => this.checkTime() : undefined);
        this.nodes += material.simulations;
        d.materialSafetyChecked = true;
        d.materialBalanceAfterRepliesCp = material.score;
        d.materialOutcome = material.outcome;
        d.materialLossCp = material.outcome === 'DRAW' ? 0 : Math.max(0, rootMaterial - material.score);
        d.tacticalReplyCount = material.repliesExamined;
        d.tacticalVariation = material.line;
        d.opponentBestReply = reply ?? material.reply;
        d.score = next.isGameOver ? this.terminal(next, player, 1)! : reply ? -MATE + 2 :
          material.outcome ? material.score :
          -this.evaluate(next, topology, 1) + material.score - SpellChessMaterialSafety.balance(next, player);
        children.push({ action, state: next, diagnostic: d });
      } catch (error) {
        if (error instanceof SearchTimeout) {
          this.timedOut = true; rootExhausted = false;
          d.rejectionReason = 'Budget expired during material inspection; candidate excluded'; break;
        }
        d.legal = false; d.rejectionReason = String(error);
        // A generated action rejected by the shared rules is a structural error, never a manual move.
        throw new Error(`Spell simulation rejected ${JSON.stringify(action)}: ${String(error)}`);
      }
    }
    if (!children.length) throw new Error('No validated Spell Chess candidate.');
    this.timedOut ||= performance.now() >= this.deadline;
    const safe = children.filter((c) => !c.diagnostic.allowsImmediateKingCapture);
    const candidates = (safe.length ? safe : children).sort((a, b) => b.diagnostic.score - a.diagnostic.score);
    let best = candidates[0];
    let score = best.diagnostic.score;
    let pv = [best.action, ...(best.diagnostic.tacticalVariation ?? [])];
    let completedDepth = immediate || rootExhausted ? 1 : 0;
    if (completedDepth === 1) for (const child of children) child.diagnostic.completedDepth = 1;
    if (!immediate && !this.timedOut) for (let depth = 2; depth <= maxDepth; depth++) {
      let iterationBest = best;
      let iterationScore = -Infinity;
      let rootAlpha = -Infinity;
      let iterationPV: SpellChessTurnAction[] = [];
      const iterationDiagnostics: Array<{ d: CandidateDiagnostic; value: NodeResult }> = [];
      try {
        for (const child of candidates) {
          this.checkTime();
          const value = child.diagnostic.allowsImmediateKingCapture
            ? { score: MATE - 2, pv: [child.diagnostic.opponentBestReply!] }
            : this.negamax(child.state, topology, depth - 1, -Infinity, -rootAlpha, 1);
          iterationDiagnostics.push({ d: child.diagnostic, value });
          if (-value.score > iterationScore) { iterationScore = -value.score; iterationBest = child; iterationPV = [child.action, ...value.pv]; }
          rootAlpha = Math.max(rootAlpha, -value.score);
        }
        best = iterationBest; score = iterationScore; pv = iterationPV; completedDepth = depth;
        for (const { d, value } of iterationDiagnostics) { d.score = -value.score; d.completedDepth = depth; d.opponentBestReply = value.pv[0]; }
        candidates.sort((a, b) => b.diagnostic.score - a.diagnostic.score);
        if (Math.abs(score) >= MATE - 20) break;
      } catch (error) { if (!(error instanceof SearchTimeout)) throw error; this.timedOut = true; break; }
    }
    const elapsedMs = performance.now() - start;
    return { bestAction: best.action, evaluationCentipawns: score, depthReached: completedDepth,
      nodesEvaluated: this.nodes, elapsedMs, trace: { engine: 'SPELL_COMPOSITE', depthReached: completedDepth,
        nodesSearched: this.nodes, elapsedMs, legalTurnActionsConsidered: diagnostics.length,
        chosenAction: best.action, principalVariation: pv, candidates: diagnostics, timedOut: this.timedOut,
        fallbackUsed: false, quiescenceNodes: this.qnodes,
        rootFullyEnumerated: rootExhausted, materialInspectionCompleted: true,
        exchangePlyLimit: 3,
        topCandidates: [...diagnostics].filter((d) => d.materialSafetyChecked).sort((a, b) => b.score - a.score).slice(0, 5)
          .map((d) => ({ spell: d.action.spell, move: `${d.action.move.from}->${d.action.move.to}`, score: d.score })) } };
  }

  private terminal(domain: IDomainState, player: PlayerId, ply: number): number | undefined {
    if (!domain.isGameOver) return undefined;
    return domain.winnerId === null ? 0 : domain.winnerId === player ? MATE - ply : -MATE + ply;
  }
  private evaluate(domain: IDomainState, topology: ITopology, ply: number): number {
    return SpellChessPositionEvaluator.evaluate(domain, domain.activePlayer, topology,
      SpellChessSearch.resources(domain, domain.activePlayer), SpellChessSearch.resources(domain, opposite(domain.activePlayer)), [], [], ply);
  }
  private negamax(domain: IDomainState, topology: ITopology, depth: number, alpha: number, beta: number, ply: number): NodeResult {
    this.checkTime(); this.nodes++;
    const terminal = this.terminal(domain, domain.activePlayer, ply);
    if (terminal !== undefined) return { score: terminal, pv: [] };
    const immediate = SpellChessMoveGenerator.findKingCapture(domain, domain.activePlayer, topology);
    if (immediate) return { score: MATE - ply - 1, pv: [immediate] };
    if (depth <= 0) return this.quiescence(domain, topology, alpha, beta, ply, 2);
    const originalAlpha = alpha, originalBeta = beta;
    const key = this.tt.computeKey(domain, domain.activePlayer, SpellChessSearch.resources(domain, 'P1'), SpellChessSearch.resources(domain, 'P2'), [], []);
    const cached = this.tt.get(key);
    if (cached && cached.depth >= depth && (cached.flag === 'EXACT' ||
      (cached.flag === 'LOWERBOUND' && cached.score >= beta) || (cached.flag === 'UPPERBOUND' && cached.score <= alpha))) {
      return { score: cached.score, pv: cached.principalVariation ?? [] };
    }
    const actions = SpellChessMoveGenerator.iterateTurnActions(domain, domain.activePlayer, topology, SpellChessSearch.resources(domain, domain.activePlayer));
    let best: NodeResult = { score: -Infinity, pv: [] };
    for (const action of actions) {
      this.checkTime();
      const next = OfficialSpellRules.simulate(domain, action, topology);
      const value = this.negamax(next, topology, depth - 1, -beta, -alpha, ply + 1);
      if (-value.score > best.score) best = { score: -value.score, pv: [action, ...value.pv] };
      alpha = Math.max(alpha, best.score);
      if (alpha >= beta) break;
    }
    if (best.score === -Infinity) return { score: this.evaluate(domain, topology, ply), pv: [] };
    this.tt.set(key, { key, depth, score: best.score, bestAction: best.pv[0], principalVariation: best.pv,
      flag: best.score <= originalAlpha ? 'UPPERBOUND' : best.score >= originalBeta ? 'LOWERBOUND' : 'EXACT' });
    return best;
  }
  private quiescence(domain: IDomainState, topology: ITopology, alpha: number, beta: number, ply: number, remaining: number): NodeResult {
    this.checkTime(); this.qnodes++;
    const terminal = this.terminal(domain, domain.activePlayer, ply);
    if (terminal !== undefined) return { score: terminal, pv: [] };
    const win = SpellChessMoveGenerator.findKingCapture(domain, domain.activePlayer, topology);
    if (win) return { score: MATE - ply - 1, pv: [win] };
    // Threat probe only: expire effects at this turn's boundary, without adjudicating a null move.
    const probe = OfficialSpellRules.sync({ ...domain, activePlayer: opposite(domain.activePlayer),
      metadata: { ...domain.metadata, hasCastSpellThisTurn: false } }, OfficialSpellEngine.advanceTurn(
      OfficialSpellRules.getState(domain), domain.activePlayer === 'P1' ? 'WHITE' : 'BLACK'));
    const royalThreat = Boolean(SpellChessMoveGenerator.findKingCapture(probe, probe.activePlayer, topology));
    const majorThreat = OfficialSpellRules.pieces(domain).some((p) => p.ownerId === domain.activePlayer &&
      (SpellChessMaterialSafety.values[p.variantId] ?? 0) >= 500 &&
      SpellChessMoveGenerator.findCapture(probe, probe.activePlayer, topology, p.position));
    const threatened = royalThreat || majorThreat;
    const standPat = this.evaluate(domain, topology, ply);
    if (remaining === 0) {
      if (!threatened) return { score: standPat, pv: [] };
      const material = SpellChessMaterialSafety.inspect(probe, domain.activePlayer, topology, () => this.checkTime(), undefined, 2, ply);
      this.nodes += material.simulations;
      return { score: material.outcome ? material.score :
        standPat + Math.min(0, material.score - SpellChessMaterialSafety.balance(domain, domain.activePlayer)), pv: [] };
    }
    let best: NodeResult = { score: threatened ? -Infinity : standPat, pv: [] };
    if (!threatened) { if (standPat >= beta) return best; alpha = Math.max(alpha, standPat); }
    // Quiet evasions and defensive Freeze are necessary when a major piece is hanging too.
    const resources = SpellChessSearch.resources(domain, domain.activePlayer);
    const actions = SpellChessMoveGenerator.iterateTurnActions(domain, domain.activePlayer, topology,
      resources, [], [], undefined, !threatened);
    for (const action of actions) {
      this.checkTime(); this.nodes++;
      const next = OfficialSpellRules.simulate(domain, action, topology);
      const reply = this.quiescence(next, topology, -beta, -alpha, ply + 1, remaining - 1);
      if (-reply.score > best.score) best = { score: -reply.score, pv: [action, ...reply.pv] };
      alpha = Math.max(alpha, best.score);
      if (alpha >= beta) break;
    }
    return best.score === -Infinity ? { score: 0, pv: [] } : best;
  }
  private checkTime(): void { if (performance.now() >= this.deadline) throw new SearchTimeout(); }
}

/**
 * ChessInReact - Spell Chess Threat Analyzer (Spec 15 § 4 Estratégia 7, RF-15-06)
 *
 * Geometric ray tracing and tactical threat detection for Spell Chess:
 * - Detects 0-obstacle direct threats to royals and high-value pieces.
 * - Detects 1-obstacle Jump rays where an intermediate piece can be leaped over.
 * - Identifies the exact obstacle square for offensive or defensive Jump tactics.
 */

import { IDomainState } from '../../../../core/state/gameState';
import { PlayerId, CoordinateKey, EntityId } from '../../../../core/coordinates/types';
import { CheckValidator } from '../../../../engine/rules/CheckValidator';
import { ITopology } from '../../../../core/topology/types';

export interface IJumpRayThreat {
  readonly attackingPieceId: string;
  readonly attackingCoord: string;
  readonly targetCoord: string;
  readonly obstacleCoord: string;
  readonly obstaclePieceId: string;
  readonly attackingVariant: string;
}

export class SpellChessThreatAnalyzer {
  public static parseCoord(coord: string): [number, number] {
    const parts = coord.split(',').map(Number);
    return [parts[0] ?? 0, parts[1] ?? 0];
  }

  public static toCoord(x: number, y: number): string {
    return `${x},${y}`;
  }

  /**
   * Finds the coordinate of a player's King in the domain.
   */
  public static findKingCoord(domain: IDomainState, owner: PlayerId): string | null {
    for (const entity of Object.values(domain.boardEntities)) {
      if (
        entity &&
        entity.type === 'PIECE' &&
        !entity.isCaptured &&
        entity.ownerId === owner &&
        (entity.variantId.toUpperCase() === 'KING' || entity.variantId.toUpperCase() === 'K')
      ) {
        return entity.position;
      }
    }
    return null;
  }

  /**
   * Scans all opponent sliding pieces (Queen, Rook, Bishop) to find any rays
   * directed at targetCoord having EXACTLY 1 intermediate obstacle.
   */
  public static detectOneObstacleJumpRays(
    domain: IDomainState,
    targetCoord: string,
    targetOwner: PlayerId,
    customOccupancy?: Record<string, string>
  ): IJumpRayThreat[] {
    const threats: IJumpRayThreat[] = [];
    const occ = customOccupancy ?? (domain.occupancy as Record<string, string>);
    const [tx, ty] = this.parseCoord(targetCoord);

    for (const entity of Object.values(domain.boardEntities)) {
      if (
        !entity ||
        entity.type !== 'PIECE' ||
        entity.isCaptured ||
        entity.ownerId === targetOwner ||
        entity.ownerId === 'NONE' ||
        entity.metadata?.isFrozen
      ) {
        continue;
      }

      const piecePos = entity.position;
      if (customOccupancy && customOccupancy[piecePos] !== entity.id) {
        continue;
      }

      const variant = entity.variantId.toUpperCase();
      const isQueen = variant === 'QUEEN' || variant === 'Q';
      const isRook = variant === 'ROOK' || variant === 'R';
      const isBishop = variant === 'BISHOP' || variant === 'B';

      if (!isQueen && !isRook && !isBishop) continue;

      const [px, py] = this.parseCoord(piecePos);
      const dx = tx - px;
      const dy = ty - py;

      const isOrthogonal = (dx === 0 && dy !== 0) || (dy === 0 && dx !== 0);
      const isDiagonal = Math.abs(dx) === Math.abs(dy) && dx !== 0;

      if ((isRook && !isOrthogonal) || (isBishop && !isDiagonal) || (!isOrthogonal && !isDiagonal)) {
        continue;
      }

      const stepX = Math.sign(dx);
      const stepY = Math.sign(dy);

      const obstacles: Array<{ coord: string; pieceId: string }> = [];
      let cx = px + stepX;
      let cy = py + stepY;

      while (cx !== tx || cy !== ty) {
        const curCoord = this.toCoord(cx, cy);
        const occId = occ[curCoord];
        if (occId && !domain.boardEntities[occId as EntityId]?.metadata?.canBeJumpedOver) {
          obstacles.push({ coord: curCoord, pieceId: occId });
        }
        cx += stepX;
        cy += stepY;
      }

      if (obstacles.length === 1 && domain.boardEntities[obstacles[0].pieceId as EntityId]?.type === 'PIECE') {
        threats.push({
          attackingPieceId: entity.id,
          attackingCoord: piecePos,
          targetCoord,
          obstacleCoord: obstacles[0].coord,
          obstaclePieceId: obstacles[0].pieceId,
          attackingVariant: variant,
        });
      }
    }

    return threats;
  }

  /**
   * Detects all pieces delivering direct attack / check against targetCoord.
   */
  public static detectDirectAttacks(
    domain: IDomainState,
    targetCoord: string,
    attackerOwner: PlayerId,
    topology: ITopology
  ): Array<{ attackingPieceId: string; attackingCoord: string; variantId: string }> {
    const attackers: Array<{ attackingPieceId: string; attackingCoord: string; variantId: string }> = [];
    const targetKey = targetCoord as CoordinateKey;

    for (const entity of Object.values(domain.boardEntities)) {
      if (
        !entity ||
        entity.type !== 'PIECE' ||
        entity.isCaptured ||
        entity.ownerId !== attackerOwner ||
        entity.metadata?.isFrozen
      ) {
        continue;
      }

      if (CheckValidator.isSquareAttacked(targetKey, attackerOwner, domain, topology)) {
        // Confirm if this piece specifically attacks targetKey
        // Create a test domain without this piece to see if attack disappears
        const testDomain: IDomainState = {
          ...domain,
          occupancy: { ...domain.occupancy },
          boardEntities: { ...domain.boardEntities },
        };
        delete testDomain.occupancy[entity.position];
        delete testDomain.boardEntities[entity.id as EntityId];

        const stillAttacked = CheckValidator.isSquareAttacked(targetKey, attackerOwner, testDomain, topology);
        if (!stillAttacked) {
          attackers.push({
            attackingPieceId: entity.id,
            attackingCoord: entity.position,
            variantId: entity.variantId,
          });
        }
      }
    }

    return attackers;
  }

  /**
   * Checks if a straight ray between from and to strictly passes through target square.
   */
  public static rayPassesThroughSquare(from: string, to: string, target: string): boolean {
    const [fx, fy] = this.parseCoord(from);
    const [tx, ty] = this.parseCoord(to);
    const [mx, my] = this.parseCoord(target);

    const dx = tx - fx;
    const dy = ty - fy;
    const stepX = Math.sign(dx);
    const stepY = Math.sign(dy);

    if (stepX === 0 && stepY === 0) return false;
    if (stepX !== 0 && stepY !== 0 && Math.abs(dx) !== Math.abs(dy)) return false;

    let curX = fx + stepX;
    let curY = fy + stepY;
    while (curX !== tx || curY !== ty) {
      if (curX === mx && curY === my) return true;
      curX += stepX;
      curY += stepY;
    }
    return false;
  }
}

/**
 * ChessInReact - Spell Chess Composite Turn Action Contracts (Spec 15 § 4 Estratégia 7, RF-15-06)
 *
 * Models a complete Spell Chess turn as an atomic composite unit:
 *   SpellChessTurnAction = Optional Spell + Mandatory Piece Move
 */

export type SpellAction =
  | { readonly type: 'NONE' }
  | { readonly type: 'FREEZE'; readonly targetSquare: string }
  | { readonly type: 'JUMP'; readonly targetSquare: string };

export interface SpellChessTurnAction {
  readonly spell: SpellAction;
  readonly move: {
    readonly pieceId: string;
    readonly from: string;
    readonly to: string;
    readonly promotion?: string;
    readonly isCapture?: boolean;
  };
}

export interface SpellResources {
  freezeRemaining: number;
  jumpRemaining: number;
  freezeCooldown: number;
  jumpCooldown: number;
}

export interface SpellChessDecisionTrace {
  depthReached: number;
  nodesSearched: number;
  elapsedMs: number;
  legalTurnActionsConsidered: number;
  topCandidates: Array<{
    spell: SpellAction;
    move: string;
    score: number;
  }>;
  chosenAction: SpellChessTurnAction;
  principalVariation: SpellChessTurnAction[];
  candidates?: CandidateDiagnostic[];
  engine?: 'SPELL_COMPOSITE';
  timedOut?: boolean;
  fallbackUsed?: boolean;
  quiescenceNodes?: number;
  rootFullyEnumerated?: boolean;
  materialInspectionCompleted?: boolean;
  exchangePlyLimit?: number;
}

export interface CandidateDiagnostic {
  action: SpellChessTurnAction;
  legal: boolean;
  score: number;
  completedDepth: number;
  opponentBestReply?: SpellChessTurnAction;
  allowsImmediateKingCapture: boolean;
  safetyChecked: boolean;
  usedFallback: boolean;
  rejectionReason?: string;
  capturedMaterialCp: number;
  materialSafetyChecked?: boolean;
  materialBalanceAfterRepliesCp?: number;
  materialLossCp?: number;
  tacticalReplyCount?: number;
  tacticalVariation?: SpellChessTurnAction[];
  materialOutcome?: 'WIN' | 'LOSS' | 'DRAW';
}
